async function getListaPreciosVentaAlPublico() {
  try {
    let pool = await sql.connect(plataforma);
    let listaprecios = await pool
      .request()
      .query(
        "DECLARE @COTI_MONE TABLE(COTI_COTIZACION DECIMAL(14,5), COTI_FECHA DATETIME, COTI_MONEDA1 VARCHAR(3), COTI_MONEDA2 VARCHAR(3)) INSERT INTO @COTI_MONE SELECT SIST_COTI.COTI_COTIZACION, SIST_COTI.COTI_FECHA, SIST_COTI.COTI_MONEDA1, SIST_COTI.COTI_MONEDA2 FROM SIST_COTI WITH(NOLOCK) WHERE SIST_COTI.COTI_FECHA < GETDATE() DECLARE @Lista_precios_todas TABLE (ARTS_ARTICULO_EMP VARCHAR(30), ARTS_NOMBRE VARCHAR(70), ARPV_ARTICULO INT, ARPV_LISTA_PRECVTA INT, ARPV_PRECIO_VTA DECIMAL(14,4), ARPV_MONEDA VARCHAR(3), MaxDeCOTI_FECHA DATETIME, CIMP_TASA DECIMAL(7,4), ARTS_CLASIF_2 VARCHAR(10), CA02_NOMBRE VARCHAR(30), ARTS_UNIMED_HOMSTO VARCHAR(3), ARTS_FACTOR_HOMSTO DECIMAL(20,12), ARVE_BLOQUEO_VENTA DECIMAL(1,0)) INSERT INTO @Lista_precios_todas SELECT STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE ,VENT_ARPV.ARPV_ARTICULO ,VENT_ARPV.ARPV_LISTA_PRECVTA ,VENT_ARPV.ARPV_PRECIO_VTA ,VENT_ARPV.ARPV_MONEDA ,Max([@COTI_MONE].COTI_FECHA) AS MaxDeCOTI_FECHA ,SIST_CIMP.CIMP_TASA ,STOC_ARTS.ARTS_CLASIF_2 ,STOC_CA02.CA02_NOMBRE ,STOC_ARTS.ARTS_UNIMED_HOMSTO ,STOC_ARTS.ARTS_FACTOR_HOMSTO ,STOC_ARVE.ARVE_BLOQUEO_VENTA FROM STOC_ARVE WITH (NOLOCK) INNER JOIN (STOC_CA02 WITH (NOLOCK) INNER JOIN (STOC_ARTS WITH (NOLOCK) INNER JOIN (((VENT_ARPV WITH (NOLOCK) LEFT JOIN @COTI_MONE ON VENT_ARPV.ARPV_MONEDA = [@COTI_MONE].COTI_MONEDA1) INNER JOIN VENT_ARVI WITH (NOLOCK) ON VENT_ARPV.ARPV_ARTICULO = VENT_ARVI.ARVI_ARTICULO) INNER JOIN SIST_CIMP WITH (NOLOCK) ON (VENT_ARVI.ARVI_CATEGORIA_IMP = SIST_CIMP.CIMP_CATEGORIA_IMP) AND (VENT_ARVI.ARVI_IMPUESTO = SIST_CIMP.CIMP_IMPUESTO)) ON STOC_ARTS.ARTS_ARTICULO = VENT_ARPV.ARPV_ARTICULO) ON STOC_CA02.CA02_CLASIF_2 = STOC_ARTS.ARTS_CLASIF_2) ON STOC_ARVE.ARVE_ARTICULO = STOC_ARTS.ARTS_ARTICULO GROUP BY STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE ,VENT_ARPV.ARPV_ARTICULO ,VENT_ARPV.ARPV_LISTA_PRECVTA ,VENT_ARPV.ARPV_PRECIO_VTA ,VENT_ARPV.ARPV_MONEDA ,SIST_CIMP.CIMP_TASA ,STOC_ARTS.ARTS_CLASIF_2 ,STOC_CA02.CA02_NOMBRE ,STOC_ARTS.ARTS_UNIMED_HOMSTO ,STOC_ARTS.ARTS_FACTOR_HOMSTO ,STOC_ARVE.ARVE_BLOQUEO_VENTA HAVING (((STOC_ARVE.ARVE_BLOQUEO_VENTA)=0)) ORDER BY Max([@COTI_MONE].COTI_FECHA) SELECT [@Lista_precios_todas].ARTS_ARTICULO_EMP ,[@Lista_precios_todas].ARTS_NOMBRE ,[@Lista_precios_todas].ARPV_LISTA_PRECVTA ,[@Lista_precios_todas].ARPV_PRECIO_VTA ,[@Lista_precios_todas].ARPV_MONEDA ,SIST_COTI.COTI_COTIZACION ,[@Lista_precios_todas].CIMP_TASA ,[@Lista_precios_todas].ARTS_CLASIF_2 ,[@Lista_precios_todas].CA02_NOMBRE ,[@Lista_precios_todas].ARTS_UNIMED_HOMSTO ,[@Lista_precios_todas].ARTS_FACTOR_HOMSTO ,CASE WHEN SIST_COTI.COTI_COTIZACION = [COTI_COTIZACION] THEN [ARPV_PRECIO_VTA]*(CASE WHEN [ARPV_LISTA_PRECVTA]=100 THEN 1 ELSE 0.8 END)*[COTI_COTIZACION] ELSE [ARPV_PRECIO_VTA]*(CASE WHEN [ARPV_LISTA_PRECVTA]=100 THEN 1 ELSE 0.8 END) END AS [Precio_base_pesos_contado_SI] ,CAST(CASE WHEN ARTS_CLASIF_2='0004' THEN ROUND(1/NULLIF([ARTS_FACTOR_HOMSTO],0),4) ELSE 0 END AS decimal(18,4)) AS [M2xCaja] ,CONVERT(date, GETDATE()) AS [Fecha_impresion] ,FORMAT(SYSDATETIME(), N'hh:mm tt') AS [Hora_impresion] FROM @Lista_precios_todas LEFT JOIN SIST_COTI WITH (NOLOCK) ON ([@Lista_precios_todas].ARPV_MONEDA = SIST_COTI.COTI_MONEDA1) AND ([@Lista_precios_todas].MaxDeCOTI_FECHA = SIST_COTI.COTI_FECHA) WHERE (([@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=1 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=2 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=3 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=4 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=5 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=6 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=7 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=8 OR [@Lista_precios_todas].[ARPV_LISTA_PRECVTA]=100))",
      );
    return listaprecios.recordsets;
  } catch (error) {
    console.error(error);
  }
}

