async function getStockPartidaconvencimiento() {
  try {
    const ArrayDepositoANoConsiderar = [];
    let urlArray =
      `${process.env.URL_API}` + "depositoanoconsiderarparastockfisico";
    await axios
      .get(urlArray, {
        httpsAgent,
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((response) => {
        results = [];
        data = response.data;
        for (var i = 0; i < data.length; i++) {
          results.push(data[i]["codigo_deposito"]);
        }
        return ArrayDepositoANoConsiderar.push(results);
      })
      .catch((error) => {
        console.error(error);
      });
    const DepositoANoConsiderar = ArrayDepositoANoConsiderar[0];
    let pool = await sql.connect(plataforma);
    let listaStock = await pool
      .request()
      .query(
        "DECLARE @Depos_A_No_considerar_para_stock_fisico TABLE(Cod_Depos INT, Nomb_Depos VARCHAR(30)) INSERT INTO @Depos_A_No_considerar_para_stock_fisico SELECT STOC_DPOS.DPOS_DEPOSITO AS Cod_Depos ,STOC_DPOS.DPOS_NOMBRE AS Nomb_Depos FROM STOC_DPOS WITH (NOLOCK) WHERE STOC_DPOS.DPOS_DEPOSITO IN (" +
          DepositoANoConsiderar +
          ") SELECT STOC_ARTS.ARTS_ARTICULO ,STOC_ARTS.ARTS_NOMBRE ,STOC_ARTS.ARTS_ARTICULO_EMP ,Sum(STOC_SDPP.SDPP_STOCK_ACT) AS SumaDeSDPP_STOCK_ACT ,STOC_PART.PART_FECHA_VTO FROM ((STOC_ARTS INNER JOIN STOC_SDPP ON STOC_ARTS.ARTS_ARTICULO = STOC_SDPP.SDPP_ARTICULO) INNER JOIN STOC_PART ON STOC_SDPP.SDPP_PARTIDA = STOC_PART.PART_PARTIDA) LEFT JOIN @Depos_A_No_considerar_para_stock_fisico ON STOC_SDPP.SDPP_DEPOSITO = [@Depos_A_No_considerar_para_stock_fisico].[Cod_Depos] GROUP BY STOC_ARTS.ARTS_ARTICULO ,STOC_ARTS.ARTS_NOMBRE ,STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_PART.PART_FECHA_VTO ,[@Depos_A_No_considerar_para_stock_fisico].[Nomb_Depos] HAVING (((Sum(STOC_SDPP.SDPP_STOCK_ACT))>0) AND ((STOC_PART.PART_FECHA_VTO) Is Not Null AND (STOC_PART.PART_FECHA_VTO)<=CONVERT(date, GETDATE())) AND (([@Depos_A_No_considerar_para_stock_fisico].[Nomb_Depos]) Is Null)) ",
      );
    return listaStock.recordsets;
  } catch (error) {
    console.error(error);
  }
}

