async function getNPPendienteEntrega() {
  try {
    const Array = [];
    let urlArrayNPaConsiderar =
      `${process.env.URL_API}` +
      "npaconsiderar"(
        await axios.get(urlArrayNPaConsiderar, {
          httpsAgent,
          headers: { Authorization: `Bearer ${token}` },
        }),
      ).data.forEach((item) => Array.push(item["cod_comp"]));
    const NPaConsiderar = Array[0].map((x) => `'${x}'`);
    const NPaConsiderarWithCommas = NPaConsiderar.join(",");
    let pool = await sql.connect(plataforma);
    let listaNP = await pool
      .request()
      .query(
        "DECLARE @NP_A_Considerar TABLE(Cod_Comp VARCHAR(30), Nomb_Comp VARCHAR(30)) INSERT INTO @NP_A_Considerar SELECT VENT_TCVE.TCVE_TIPO_COM AS Cod_Comp ,VENT_TCVE.TCVE_NOMBRE AS Nomb_Comp FROM VENT_TCVE WITH (NOLOCK) WHERE VENT_TCVE.TCVE_TIPO_COM IN (" +
          NPaConsiderarWithCommas +
          ") DECLARE @NP_Pendientes_entrega TABLE( NPCA_FECHA_EMI DATETIME, NPCA_DIVISION_NPCA SMALLINT, NPCA_TIPO_NPCA VARCHAR(3), NPCA_NUMERO_NPCA DECIMAL(10,0), ARTS_ARTICULO_EMP VARCHAR(30), ARTS_NOMBRE VARCHAR(70), NPDE_UNIMED VARCHAR(3), NPDE_CANT_PEDIDA DECIMAL(14,4), NPDE_CANT_ENTREG DECIMAL(14,4), NPDE_MOTIVO_CANC VARCHAR(3), Uni_Pte_Entr_NP DECIMAL(12,2), ARTS_FACTOR_HOMSTO DECIMAL(24,14), ARTS_CLASIF_2 VARCHAR(10)) INSERT INTO @NP_Pendientes_entrega SELECT VENT_NPCA.NPCA_FECHA_EMI ,VENT_NPCA.NPCA_DIVISION_NPCA ,VENT_NPCA.NPCA_TIPO_NPCA ,VENT_NPCA.NPCA_NUMERO_NPCA ,STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE ,VENT_NPDE.NPDE_UNIMED ,VENT_NPDE.NPDE_CANT_PEDIDA ,VENT_NPDE.NPDE_CANT_ENTREG ,VENT_NPDE.NPDE_MOTIVO_CANC ,[NPDE_CANT_PEDIDA]-[NPDE_CANT_ENTREG] AS [Uni_Pte_Entr_NP] ,STOC_ARTS.ARTS_FACTOR_HOMSTO ,STOC_ARTS.ARTS_CLASIF_2 FROM @NP_A_Considerar INNER JOIN ((VENT_NPCA WITH (NOLOCK) INNER JOIN VENT_NPDE WITH (NOLOCK) ON (VENT_NPCA.NPCA_NUMERO_NPCA = VENT_NPDE.NPDE_NUMERO_NPCA) AND (VENT_NPCA.NPCA_TIPO_NPCA = VENT_NPDE.NPDE_TIPO_NPCA) AND (VENT_NPCA.NPCA_DIVISION_NPCA = VENT_NPDE.NPDE_DIVISION_NPCA)) INNER JOIN STOC_ARTS WITH (NOLOCK) ON VENT_NPDE.NPDE_ARTICULO = STOC_ARTS.ARTS_ARTICULO) ON [@NP_A_Considerar].[Cod_Comp] = VENT_NPCA.NPCA_TIPO_NPCA WHERE (((VENT_NPDE.NPDE_MOTIVO_CANC) Is Null)) DECLARE @NP_Pendientes_entrega2 TABLE( NPCA_FECHA_EMI DATETIME, NPCA_DIVISION_NPCA SMALLINT, NPCA_TIPO_NPCA VARCHAR(3), NPCA_NUMERO_NPCA DECIMAL(10,0), ARTS_ARTICULO_EMP VARCHAR(30), ARTS_NOMBRE VARCHAR(70), NPDE_UNIMED VARCHAR(3), NPDE_CANT_PEDIDA DECIMAL(14,4), NPDE_CANT_ENTREG DECIMAL(14,4), NPDE_MOTIVO_CANC VARCHAR(3), Uni_Pte_Entr_NP DECIMAL(12,2), ARTS_FACTOR_HOMSTO DECIMAL(24,14), NP_UniM2_Pte_Entr DECIMAL(12,2), ARTS_CLASIF_2 VARCHAR(10) ) INSERT INTO @NP_Pendientes_entrega2 SELECT [@NP_Pendientes_entrega].NPCA_FECHA_EMI ,[@NP_Pendientes_entrega].NPCA_DIVISION_NPCA ,[@NP_Pendientes_entrega].NPCA_TIPO_NPCA ,[@NP_Pendientes_entrega].NPCA_NUMERO_NPCA ,[@NP_Pendientes_entrega].ARTS_ARTICULO_EMP ,[@NP_Pendientes_entrega].ARTS_NOMBRE ,[@NP_Pendientes_entrega].NPDE_UNIMED ,[@NP_Pendientes_entrega].NPDE_CANT_PEDIDA ,[@NP_Pendientes_entrega].NPDE_CANT_ENTREG ,[@NP_Pendientes_entrega].NPDE_MOTIVO_CANC ,[@NP_Pendientes_entrega].Uni_Pte_Entr_NP ,[@NP_Pendientes_entrega].ARTS_FACTOR_HOMSTO ,IIf([ARTS_CLASIF_2]='0004',Round([@NP_Pendientes_entrega].[Uni_Pte_Entr_NP]/[ARTS_FACTOR_HOMSTO],3) ,[@NP_Pendientes_entrega].[Uni_Pte_Entr_NP]) AS [NP_UniM2_Pte_Entr] ,[@NP_Pendientes_entrega].ARTS_CLASIF_2 FROM @NP_Pendientes_entrega WHERE ((([@NP_Pendientes_entrega].[Uni_Pte_Entr_NP])>0)) SELECT [@NP_Pendientes_entrega2].NPCA_TIPO_NPCA ,[@NP_Pendientes_entrega2].ARTS_ARTICULO_EMP ,[@NP_Pendientes_entrega2].ARTS_NOMBRE ,Sum([@NP_Pendientes_entrega2].[Uni_Pte_Entr_NP]) AS [Uni_Pte_Entr_NP] ,Sum([@NP_Pendientes_entrega2].[NP_UniM2_Pte_Entr]) AS [NP_UniM2_Pte_Entr] FROM @NP_Pendientes_entrega2 GROUP BY [@NP_Pendientes_entrega2].NPCA_TIPO_NPCA ,[@NP_Pendientes_entrega2].ARTS_ARTICULO_EMP ,[@NP_Pendientes_entrega2].ARTS_NOMBRE",
      );
    return listaNP.recordsets;
  } catch (error) {
    console.error(error);
  }
}

