async function gdc_itemreclamadosalproveedor() {
  try {
    let urlArray = `${process.env.URL_API}` + "gdc/clasif8artquesecompran";
    const raw_array = (
      await axios(urlArray, {
        httpsAgent,
        headers: { Authorization: `Bearer ${token}` },
      })
    ).data;
    const response2 = raw_array.map((item) => item.Cod_clasif8);
    let clasif8artquesecompran = response2
      .sort(function (a, b) {
        return a - b;
      })
      .join(",");
    //console.log(clasif8artquesecompran);
    let pool = await sql.connect(plataforma);
    let gdc_itemreclamadosalproveedor = await pool
      .request()
      .query(
        "WITH ArtQueSeCompranSegunClas8yRCMercado AS( SELECT STOC_ARCO.ARCO_RUBRO_COMPRA ,CPAG_RUBC.RUBC_NOMBRE ,STOC_ARTS.ARTS_ARTICULO ,STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE ,STOC_CA08.CA08_CLASIF_8 ,STOC_CA08.CA08_NOMBRE FROM CPAG_RUBC WITH (NOLOCK) INNER JOIN ((STOC_ARCO WITH (NOLOCK) INNER JOIN STOC_ARTS WITH (NOLOCK) ON STOC_ARCO.ARCO_ARTICULO = STOC_ARTS.ARTS_ARTICULO) INNER JOIN STOC_CA08 WITH (NOLOCK) ON STOC_ARTS.ARTS_CLASIF_8 = STOC_CA08.CA08_CLASIF_8) ON CPAG_RUBC.RUBC_RUBRO_COMPRA = STOC_ARCO.ARCO_RUBRO_COMPRA WHERE (((CPAG_RUBC.RUBC_NOMBRE) LIKE '%(1)%')) AND STOC_CA08.CA08_CLASIF_8 IN (" +
          clasif8artquesecompran +
          ")) SELECT COMP_CODC.CODC_DIVISION ,COMP_CODC.CODC_TIPO_OC ,COMP_CODC.CODC_NUM_OC ,COMP_RODC.RODC_REN_OC ,FORMAT(COMP_CODC.CODC_FECHA_OC, 'dd/MM/yyyy') AS Fecha_OC ,STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE ,SUM(IIf([RODC_CANT_PEDIDA]-[RODC_CANT_RECIB]>0,[RODC_CANT_PEDIDA]-[RODC_CANT_RECIB],0)) AS Pend_Entrega FROM ((COMP_CODC WITH (NOLOCK) INNER JOIN COMP_RODC WITH (NOLOCK) ON (COMP_CODC.CODC_NUM_OC = COMP_RODC.RODC_NUM_OC) AND (COMP_CODC.CODC_TIPO_OC = COMP_RODC.RODC_TIPO_OC) AND (COMP_CODC.CODC_DIVISION = COMP_RODC.RODC_DIVISION)) INNER JOIN STOC_ARTS WITH (NOLOCK) ON COMP_RODC.RODC_ARTICULO = STOC_ARTS.ARTS_ARTICULO) INNER JOIN ArtQueSeCompranSegunClas8yRCMercado ON STOC_ARTS.ARTS_ARTICULO = ArtQueSeCompranSegunClas8yRCMercado.ARTS_ARTICULO WHERE ((COMP_RODC.RODC_SECTOR)='100') AND ((IIf([RODC_CANT_PEDIDA]-[RODC_CANT_RECIB]>0,[RODC_CANT_PEDIDA]-[RODC_CANT_RECIB],0))>0) AND ((COMP_RODC.RODC_MOTIVO_CANC) Is Null) GROUP BY COMP_CODC.CODC_DIVISION ,COMP_CODC.CODC_TIPO_OC ,COMP_CODC.CODC_NUM_OC ,COMP_RODC.RODC_REN_OC ,COMP_CODC.CODC_FECHA_OC ,STOC_ARTS.ARTS_ARTICULO_EMP ,STOC_ARTS.ARTS_NOMBRE",
      );
    return gdc_itemreclamadosalproveedor.recordsets;
  } catch (error) {
    console.error(error);
  }
}

async function gdc_getArtsDerivados(getData) {
  try {
    //console.log(getData);
    let pool = await sql.connect(plataforma);
    let infoLista = await pool
      .request()
      .input("codigo", sql.VarChar(7), getData.codigo)
      .query(
        "SELECT * FROM [STOC_ARTS] WITH (NOLOCK) WHERE ARTS_ARTICULO_EMP LIKE '%'+ @codigo +'%' ",
      );
    return infoLista.recordsets;
  } catch (error) {
    console.error(error);
  }
}

